Question:                                                                                                                      (20 marks)

Write a C/C++ program that allow users to create a new file using the CreateFile() function. The name of the file should be “Studentinfo” and it should be a ".doc” file. The user can input their name i.e., “ABC” and roll number i.e., “XYZ”, which will be written to the file using the WriteFile() function. Additionally, the program can read and display the content of an existing file using the ReadFile() function.

Hints:
    1. Include <iostream > and <windows.h>header files in your program.
Use the GetLastError() API to get the error where required.

Solution:
#include <iostream>
#include <windows.h>

using namespace std;

int main() {
    HANDLE studentFile = CreateFile("StudentInfo.doc", GENERIC_WRITE | GENERIC_READ, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);

    if (studentFile == INVALID_HANDLE_VALUE) {
        cerr << "Failed to create file. Error: " << GetLastError() << endl;
        return 1;
    }

    string studentName, studentID;
    cout << "Enter Your Name: ";
    getline(cin, studentName);
    cout << "Enter your Student ID: ";
    getline(cin, studentID);

    string studentData = "Name: " + studentName + "\nStudent ID: " + studentID;
    DWORD bytesWritten;

    if (!WriteFile(studentFile, studentData.c_str(), studentData.size(), &bytesWritten, NULL)) {
        cerr << "Failed to write to the file. Error code: " << GetLastError() << endl;
        CloseHandle(studentFile);
        return 1;
    }

    cout << "Data Written to the File Successfully" << endl;

    SetFilePointer(studentFile, 0, NULL, FILE_BEGIN);
    char readBuffer[1024];
    DWORD bytesRead;

    if (ReadFile(studentFile, readBuffer, sizeof(readBuffer), &bytesRead, NULL)) {
        cout << "File Content:" << endl;
        cout.write(readBuffer, bytesRead);
    }
    else {
        cerr << "Failed to read the file. Error code: " << GetLastError() << endl;
    }

    CloseHandle(studentFile);
    return 0;
}

