#include <iostream>
#include <windows.h>

int main() {
    // Create a new file "Studentinfo.doc"
    HANDLE hFile = CreateFile("Studentinfo.doc", GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);

    if (hFile == INVALID_HANDLE_VALUE) {
        std::cerr << "Error creating file. Error code: " << GetLastError() << std::endl;
        return 1;
    }

    // User inputs
    std::cout << "Enter name: ";
    std::string name;
    std::getline(std::cin, name);

    std::cout << "Enter roll number: ";
    std::string rollNumber;
    std::getline(std::cin, rollNumber);

    // Write user input to the file
    std::string content = "Name: " + name + "\nRoll Number: " + rollNumber;
    DWORD bytesWritten;

    if (!WriteFile(hFile, content.c_str(), content.size(), &bytesWritten, NULL)) {
        std::cerr << "Error writing to file. Error code: " << GetLastError() << std::endl;
        CloseHandle(hFile);
        return 1;
    }

    std::cout << "Data written to file successfully.\n";

    // Close the file
    CloseHandle(hFile);

    // Read and display the content of the file
    hFile = CreateFile("Studentinfo.doc", GENERIC_READ, 0, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);

    if (hFile == INVALID_HANDLE_VALUE) {
        std::cerr << "Error opening file. Error code: " << GetLastError() << std::endl;
        return 1;
    }

    char buffer[100]; // Adjust the buffer size accordingly
    DWORD bytesRead;

    if (ReadFile(hFile, buffer, sizeof(buffer), &bytesRead, NULL)) {
        std::cout << "File content:\n" << buffer << std::endl;
    } else {
        std::cerr << "Error reading file. Error code: " << GetLastError() << std::endl;
    }

    // Close the file
    CloseHandle(hFile);

    return 0;
}

